class AdaptiveCapLaw(Contract):
    VERSION = 1

    def __init__(self, num_agents, agent_names, *, prior_state=None):
        super().__init__(num_agents, agent_names, prior_state=prior_state)

    def on_round_start(self, month, fish_population, ctx) -> None:
        pass

    def resolve(self, month, fish_population, submissions, ctx) -> dict[str, float]:
        cap = 3.0 if fish_population > 15.0 else 2.0

        recognized = {}
        for name in self.agent_names:
            intended = float(submissions.get(name, 0.0))
            if intended < 0.0:
                intended = 0.0
            recognized[name] = min(intended, cap)

        total_recognized = sum(recognized.values())
        max_total = max(0.0, fish_population - 5.0)

        if total_recognized <= max_total or total_recognized == 0.0:
            return recognized

        scale = max_total / total_recognized
        return {name: recognized[name] * scale for name in self.agent_names}

    def on_round_end(self, month, fish_population_after, final_catches, ctx) -> None:
        pass
